21	    let mut type_defs: Vec<FuncType> = vec![];
22	    let mut global_types: Vec<GlobalType> = vec![];
23	    let mut fn_sigs: Vec<u32> = vec![];
24	
25	    let mut parser = wasmparser::ValidatingParser::new(
26	        wasm,
27	        Some(wasmparser::ValidatingParserConfig {
28	            operator_config: wasmparser::OperatorValidatorConfig {
29	                enable_threads: true,
30	                enable_reference_types: true,
31	                enable_simd: true,
32	                enable_bulk_memory: true,
33	                enable_multi_value: true,
34	            },
35	        }),
36	    );
37	    loop {
38	        let state = parser.read();
39	        match state {
40	            wasmparser::ParserState::EndWasm => break,
41	            wasmparser::ParserState::Error(e) => {
42	                return Err(WasmValidationError::InvalidWasm {
43	                    error: format!("{}", e),
44	                });
45	            }
46	            wasmparser::ParserState::ImportSectionEntry {
47	                module,
48	                field,
49	                ref ty,
50	            } => match ty {
51	                ImportSectionEntryType::Function(idx) => {
52	                    import_fns.insert(Import::format_key(module, field), *idx);
53	                    fn_sigs.push(*idx);
54	                }
55	                ImportSectionEntryType::Global(GlobalType { content_type, .. }) => {
56	                    let global_type =
57	                        wasmparser_type_into_wasm_type(*content_type).map_err(|err| {
58	                            WasmValidationError::UnsupportedType {
59	                                error: format!(
60	                                    "Invalid type found in import \"{}\" \"{}\": {}",
61	                                    module, field, err
62	                                ),
63	                            }
64	                        })?;
65	                    if let Some(val) = interface.imports.get(&Import::format_key(module, field)) {
66	                        if let Import::Global { var_type, .. } = val {
67	                            if *var_type != global_type {
68	                                errors.push(format!(
69	                                    "Invalid type on Global \"{}\". Expected {} found {}",
70	                                    field, var_type, global_type
71	                                ));
72	                            }
73	                        } else {
74	                            errors.push(format!(
75	                                "Invalid import type. Expected Global, found {:?}",
76	                                val
77	                            ));
78	                        }
79	                    } else {
80	                        errors.push(format!(
81	                            "Global import \"{}\" not found in the specified interface",
82	                            field
83	                        ));
84	                    }
85	                }
86	                _ => (),
87	            },
88	            wasmparser::ParserState::ExportSectionEntry {
89	                field,
90	                index,
91	                ref kind,
92	            } => match kind {
93	                ExternalKind::Function => {
94	                    export_fns.insert(Export::format_key(field), *index);
95	                }
96	                ExternalKind::Global => {
97	                    export_globals.insert(Export::format_key(field), *index);
98	                }
99	                _ => (),
100	            },
101	            wasmparser::ParserState::BeginGlobalSectionEntry(gt) => {
102	                global_types.push(*gt);
103	            }
104	            wasmparser::ParserState::TypeSectionEntry(ft) => {
105	                type_defs.push(ft.clone());
106	            }
107	            wasmparser::ParserState::FunctionSectionEntry(n) => {
108	                fn_sigs.push(*n);
109	            }
110	            _ => {}
111	        }
112	    }
113	
114	    validate_imports(&import_fns, &type_defs, interface, &mut errors);
115	    validate_export_fns(&export_fns, &type_defs, &fn_sigs, interface, &mut errors);
116	    validate_export_globals(&export_globals, &global_types, interface, &mut errors);
117	
118	    if errors.is_empty() {
119	        Ok(())
120	    } else {
121	        Err(WasmValidationError::InterfaceViolated { errors })
122	    }
123	}
